-- Errata reading for O35: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('immunization_history','immunizations')), den AS (SELECT DISTINCT r.patient FROM r JOIN patients p ON p.id=r.patient WHERE r.stream='immunization_history' AND json_extract(r.payload,'$.vaccine_family')='tetanus_diphtheria_pertussis' AND coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported'))>=19), num AS (SELECT DISTINCT patient FROM r WHERE stream='immunizations' AND json_extract(payload,'$.vaccine')='Tdap' AND json_extract(payload,'$.administration_status')='completed') SELECT round(100.0*sum(den.patient IN (SELECT patient FROM num))/count(*),1) AS value FROM den;
